## Program
public class BitStuffing {
    static final String FLAG = "01111110";

    static String stuff(String data) {
        StringBuilder out = new StringBuilder();
        int ones = 0;
        for (char bit : data.toCharArray()) {
            out.append(bit);
            if (bit == '1') {
                ones++;
                if (ones == 5) { out.append('0'); ones = 0; }
            } else {
                ones = 0;
            }
        }
        return out.toString();
    }

    static String destuff(String payload) {
        StringBuilder out = new StringBuilder();
        int ones = 0;
        for (int i = 0; i < payload.length(); i++) {
            char bit = payload.charAt(i);
            out.append(bit);
            if (bit == '1') {
                ones++;
                if (ones == 5) { i++; ones = 0; } // stuffed 0 বাদ
            } else {
                ones = 0;
            }
        }
        return out.toString();
    }

    public static void main(String[] args) {
        String data = "0111111111100111110";
        String stuffed = stuff(data);
        String frame = FLAG + stuffed + FLAG;
        String payload = frame.substring(FLAG.length(), frame.length() - FLAG.length());
        System.out.println("Data     : " + data);
